insert into public.fishing_baits ("id","name","description","price","image_path","sort_order","common_bp","rare_bp","epic_bp","mythic_bp","failure_bp","effect_kind","effect_description","success_chance_bp","fish_only","alternating") values
('bait','퐁당 지렁이','비가 갠 뒤 촉촉한 흙에서 조심스럽게 데려온 퐁당섬의 작은 길잡이예요. 낚싯바늘 끝에서 꼬물거리는 모습을 보고 있으면, 처음 바다를 만났던 날의 설렘이 떠올라요.',48,'/items/baits/pongdang-worm.png',101,8650,1200,130,20,0,'fish','비가 갠 뒤 촉촉한 흙에서 조심스럽게 데려온 퐁당섬의 작은 길잡이예요. 낚싯바늘 끝에서 꼬물거리는 모습을 보고 있으면, 처음 바다를 만났던 날의 설렘이 떠올라요.',10000,false,false),
('bait_aurora_clockwork_bug','오로라 태엽벌레','작은 날개 사이로 오로라 빛이 흐르는 태엽벌레예요. 등 뒤의 태엽을 감아 물속에 내려보내면, 조용한 바닷속에서 잊고 있던 자장가가 들려온대요.',188,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/aurora-clockwork-bug.png',124,2420,7500,0,80,0,'fish','작은 날개 사이로 오로라 빛이 흐르는 태엽벌레예요. 등 뒤의 태엽을 감아 물속에 내려보내면, 조용한 바닷속에서 잊고 있던 자장가가 들려온대요.',10000,false,false),
('bait_breadcrumbs','보슬보슬 빵가루','동네 빵집에서 아침마다 구워 내는 빵의 가장 부드러운 부분을 모았어요. 손끝에 남은 고소한 향이 물결을 따라 퍼지면, 바다에도 따뜻한 아침 식탁이 차려져요.',18,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/soft-breadcrumbs.png',99,9500,500,0,0,0,'fish','동네 빵집에서 아침마다 구워 내는 빵의 가장 부드러운 부분을 모았어요. 손끝에 남은 고소한 향이 물결을 따라 퍼지면, 바다에도 따뜻한 아침 식탁이 차려져요.',10000,false,false),
('bait_cloud_dough','솜구름 반죽','해가 뜨기 전 낮게 내려온 구름을 살짝 떼어 반죽한 것처럼 폭신해요. 물 위에 올려놓으면 천천히 풀어지며, 바닷속 친구들에게 하얀 이불을 덮어 주는 듯해요.',31,'/items/baits/cloud-dough.png',110,10000,0,0,0,0,'fish','해가 뜨기 전 낮게 내려온 구름을 살짝 떼어 반죽한 것처럼 폭신해요. 물 위에 올려놓으면 천천히 풀어지며, 바닷속 친구들에게 하얀 이불을 덮어 주는 듯해요.',10000,true,false),
('bait_coral_pollen','산호 꽃가루','산호 정원에서 꽃이 피는 짧은 순간에만 모을 수 있는 은은한 가루예요. 작은 병을 기울이면 바다의 봄을 닮은 향이 번지고, 잠들어 있던 정원이 기지개를 켜요.',60,'/items/baits/coral-pollen.png',118,9600,0,400,0,0,'fish','산호 정원에서 꽃이 피는 짧은 순간에만 모을 수 있는 은은한 가루예요. 작은 병을 기울이면 바다의 봄을 닮은 향이 번지고, 잠들어 있던 정원이 기지개를 켜요.',10000,false,false),
('bait_cracked_star','금 간 별조각','밤바다에 떨어진 별에서 조심스럽게 떼어 낸 조각이에요. 금이 간 틈으로 새어 나오는 빛은 아직 따뜻해서, 손에 쥐면 먼 하늘의 이야기가 전해지는 것 같아요.',245,'/items/baits/cracked-star.png',115,0,9930,0,70,0,'fish','밤바다에 떨어진 별에서 조심스럽게 떼어 낸 조각이에요. 금이 간 틈으로 새어 나오는 빛은 아직 따뜻해서, 손에 쥐면 먼 하늘의 이야기가 전해지는 것 같아요.',10000,true,false),
('bait_deep_sleep_sachet','깊은잠 향낭','달빛에 말린 꽃잎과 바닷바람을 작은 주머니에 담았어요. 매듭을 느슨하게 풀면 포근한 향이 흘러나와, 잠들지 못한 밤에도 잔잔한 꿈을 꾸게 해 준대요.',361,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/deep-sleep-sachet-v1.png',305,0,8600,1300,100,0,'fish','달빛에 말린 꽃잎과 바닷바람을 작은 주머니에 담았어요. 매듭을 느슨하게 풀면 포근한 향이 흘러나와, 잠들지 못한 밤에도 잔잔한 꿈을 꾸게 해 준대요.',10000,false,false),
('bait_epic','별잠의 유혹','별이 잠드는 시간에만 빛나는 보랏빛 미끼예요. 물속으로 내려갈수록 잔광이 길게 이어져, 바다 아래에도 누군가의 꿈이 펼쳐지는 것처럼 보여요.',null,'/items/baits/starlit-allure.png',108,0,0,9970,30,0,'fish','별이 잠드는 시간에만 빛나는 보랏빛 미끼예요. 물속으로 내려갈수록 잔광이 길게 이어져, 바다 아래에도 누군가의 꿈이 펼쳐지는 것처럼 보여요.',10000,false,false),
('bait_firefly_pupa','반딧불 번데기','이슬 맺힌 풀숲에서 발견한 작은 빛을 조심히 감싸 두었어요. 바닷속에 내려보내도 꺼지지 않는 불빛이 깜빡이며, 길을 잃은 여행자에게 인사를 건네요.',65,'/items/baits/firefly-pupa.png',112,9550,0,450,0,0,'fish','이슬 맺힌 풀숲에서 발견한 작은 빛을 조심히 감싸 두었어요. 바닷속에 내려보내도 꺼지지 않는 불빛이 깜빡이며, 길을 잃은 여행자에게 인사를 건네요.',10000,true,false),
('bait_first_greeting','소라의 첫인사','빈 소라에 바람을 불어넣자 한 번도 들어 보지 못한 작은 인사가 흘러나왔어요. 낚싯줄 끝에서 소라가 살랑일 때마다, 오늘은 누구를 처음 만나게 될지 궁금해져요.',null,'/items/baits/conch-first-greeting.png',109,8320,1500,150,30,0,'fish','빈 소라에 바람을 불어넣자 한 번도 들어 보지 못한 작은 인사가 흘러나왔어요. 낚싯줄 끝에서 소라가 살랑일 때마다, 오늘은 누구를 처음 만나게 될지 궁금해져요.',10000,false,false),
('bait_forbidden_star','금단의 별사탕','아무도 모르는 별빛 찬장에서 꺼낸 달콤한 사탕이에요. 포장지를 벗기면 먼 은하의 향기가 나지만, 누가 처음 만들었는지는 섬의 가장 오래된 이야기에도 남아 있지 않아요.',133,'/items/baits/forbidden-star-candy.png',105,7720,1600,600,80,0,'fish','아무도 모르는 별빛 찬장에서 꺼낸 달콤한 사탕이에요. 포장지를 벗기면 먼 은하의 향기가 나지만, 누가 처음 만들었는지는 섬의 가장 오래된 이야기에도 남아 있지 않아요.',10000,false,false),
('bait_goblin_bell_cherry','도깨비 방울체리','숲속 도깨비가 가지 끝에 매달아 둔 방울을 닮은 체리예요. 물결에 흔들릴 때마다 작은 소리가 울려, 고요한 바다에서도 장난스러운 웃음이 들리는 듯해요.',207,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/goblin-bell-cherry.png',123,2100,7500,400,0,0,'fish','숲속 도깨비가 가지 끝에 매달아 둔 방울을 닮은 체리예요. 물결에 흔들릴 때마다 작은 소리가 울려, 고요한 바다에서도 장난스러운 웃음이 들리는 듯해요.',10000,true,false),
('bait_grain_dumpling','노릇노릇 곡물경단','섬에서 거둔 곡물을 곱게 빻아 노릇하게 구운 경단이에요. 따뜻할 때 살짝 눌러 만든 자국에는, 오늘도 무사히 돌아오라는 빵집 할머니의 마음이 담겨 있어요.',24,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/toasted-grain-dumpling.png',100,9000,1000,0,0,0,'fish','섬에서 거둔 곡물을 곱게 빻아 노릇하게 구운 경단이에요. 따뜻할 때 살짝 눌러 만든 자국에는, 오늘도 무사히 돌아오라는 빵집 할머니의 마음이 담겨 있어요.',10000,false,false),
('bait_grubby_magnet','꼬질 자석경단','주머니 구석에서 오래 굴러다닌 듯 꼬질꼬질한 경단이에요. 속에 숨겨 둔 작은 자석은 반짝이는 보물보다 누군가 잃어버린 낡은 물건에 더 마음이 가는 모양이에요.',8,'/items/baits/grubby-magnet-dumpling.png',103,9900,100,0,0,0,'fish','주머니 구석에서 오래 굴러다닌 듯 꼬질꼬질한 경단이에요. 속에 숨겨 둔 작은 자석은 반짝이는 보물보다 누군가 잃어버린 낡은 물건에 더 마음이 가는 모양이에요.',10000,false,false),
('bait_halfmoon_honey','반달 꿀젤리','초승달이 조금 통통해진 날, 꿀을 천천히 졸여 만든 반달 모양 젤리예요. 말랑한 표면에 비친 달빛을 보고 있으면, 물결도 잠시 걸음을 늦추는 것 같아요.',122,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/halfmoon-honey-jelly.png',120,5000,5000,0,0,0,'fish','초승달이 조금 통통해진 날, 꿀을 천천히 졸여 만든 반달 모양 젤리예요. 말랑한 표면에 비친 달빛을 보고 있으면, 물결도 잠시 걸음을 늦추는 것 같아요.',10000,true,false),
('bait_honey_dumpling','햇살 꿀경단','햇살이 가장 따뜻한 오후에 꿀을 듬뿍 발라 만든 작은 경단이에요. 바다에 내려보내면 고소하고 달콤한 향이 퍼져, 멀리서도 소풍 바구니를 열어 둔 것처럼 느껴져요.',50,'/items/baits/sunny-honey-dumpling.png',116,8200,1800,0,0,0,'fish','햇살이 가장 따뜻한 오후에 꿀을 듬뿍 발라 만든 작은 경단이에요. 바다에 내려보내면 고소하고 달콤한 향이 퍼져, 멀리서도 소풍 바구니를 열어 둔 것처럼 느껴져요.',10000,false,false),
('bait_lightning_stardust','벼락 별가루','폭풍이 물러간 밤, 바위 틈에 남은 번개빛을 모은 별가루예요. 병을 가볍게 흔들면 사라진 천둥의 장난기가 깨어나 손끝에서 작게 반짝여요.',264,'/items/baits/lightning-stardust.png',114,0,9450,550,0,0,'fish','폭풍이 물러간 밤, 바위 틈에 남은 번개빛을 모은 별가루예요. 병을 가볍게 흔들면 사라진 천둥의 장난기가 깨어나 손끝에서 작게 반짝여요.',10000,true,false),
('bait_magnet','심해 인력석','바다 깊은 곳에서 건져 올린 매끈한 돌에 푸른 빛이 맴돌아요. 가까이 대면 오래 잠들어 있던 물건들이 살짝 떨려, 돌이 잃어버린 기억을 부르는 것만 같아요.',46,'/items/baits/abyss-lodestone.png',106,8700,1200,100,0,0,'decoration','바다 깊은 곳에서 건져 올린 매끈한 돌에 푸른 빛이 맴돌아요. 가까이 대면 오래 잠들어 있던 물건들이 살짝 떨려, 돌이 잃어버린 기억을 부르는 것만 같아요.',10000,false,false),
('bait_map_compass_jelly','나침반 꿀젤리','말랑한 꿀젤리 속에 작은 금빛 나침반이 둥실 떠 있어요. 바람 한 점 없는 날에도 바늘은 천천히 움직이며, 오래전 뱃사람들이 접어 둔 항로의 꿈을 가리켜요.',160,'/items/baits/map-compass-honey-jelly-v1.png',127,6700,3000,300,0,0,'fish','말랑한 꿀젤리 속에 작은 금빛 나침반이 둥실 떠 있어요. 바람 한 점 없는 날에도 바늘은 천천히 움직이며, 오래전 뱃사람들이 접어 둔 항로의 꿈을 가리켜요.',10000,false,false),
('bait_map_lantern_berry','길잡이 등불열매','해가 지면 껍질 안쪽에서 따뜻한 불빛이 피어나는 신비로운 열매예요. 안개 낀 밤에 이 열매를 매달고 돌아온 선원들은, 바다가 먼저 집으로 가는 길을 알려 주었다고 말해요.',280,'/items/baits/map-wayfinder-lantern-berry-v1.png',128,3200,6500,300,0,0,'fish','해가 지면 껍질 안쪽에서 따뜻한 불빛이 피어나는 신비로운 열매예요. 안개 낀 밤에 이 열매를 매달고 돌아온 선원들은, 바다가 먼저 집으로 가는 길을 알려 주었다고 말해요.',10000,false,false),
('bait_map_star_chart_pearl','별지도를 품은 진주','보랏빛 조개가 품은 진주 안에 금빛 별항로가 천천히 떠올라요. 달빛이 닿으면 오래전 항해자들이 남긴 약속처럼 별들이 이어지고, 귀를 기울이면 이름 모를 섬의 파도 소리가 들려오는 듯해요.',680,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/map-star-chart-pearl-v1.png',129,1500,5000,3500,0,0,'fish','보랏빛 조개가 품은 진주 안에 금빛 별항로가 천천히 떠올라요. 달빛이 닿으면 오래전 항해자들이 남긴 약속처럼 별들이 이어지고, 귀를 기울이면 이름 모를 섬의 파도 소리가 들려오는 듯해요.',10000,false,false),
('bait_mermaid_whisper_candy','인어의 귓속말 캔디','파도가 잔잔한 밤이면 인어가 몰래 두고 간다는 작은 사탕이에요. 달콤한 향 사이에 숨은 바다의 노랫소리는 귀로 듣기보다 마음으로 느껴야 한다고 해요.',155,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/mermaid-whisper-candy.png',125,4000,6000,0,0,0,'fish','파도가 잔잔한 밤이면 인어가 몰래 두고 간다는 작은 사탕이에요. 달콤한 향 사이에 숨은 바다의 노랫소리는 귀로 듣기보다 마음으로 느껴야 한다고 해요.',10000,true,false),
('bait_moonshade_dumpling','달그늘 경단','해가 비칠 때와 달이 뜰 때 서로 다른 향을 내는 신기한 경단이에요. 그늘에 잠시 두었다가 꺼내 보면 색이 살짝 달라져, 바다가 흘려보낸 시간을 담고 있는 것 같아요.',107,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/moonshade-dumpling-v1.png',317,5500,4500,0,0,0,'fish','해가 비칠 때와 달이 뜰 때 서로 다른 향을 내는 신기한 경단이에요. 그늘에 잠시 두었다가 꺼내 보면 색이 살짝 달라져, 바다가 흘려보낸 시간을 담고 있는 것 같아요.',10000,false,false),
('bait_pearl_bubble','진주 거품방울','진주를 닦던 물 위에 떠오른 거품을 살며시 굳혀 만들었어요. 터질 듯 말 듯 맑게 빛나는 표면에는, 바닷속 작은 방에 놓일 물건들의 꿈이 비쳐요.',60,'/items/baits/pearl-bubble.png',117,6500,3500,0,0,0,'fish','진주를 닦던 물 위에 떠오른 거품을 살며시 굳혀 만들었어요. 터질 듯 말 듯 맑게 빛나는 표면에는, 바닷속 작은 방에 놓일 물건들의 꿈이 비쳐요.',10000,false,false),
('bait_pet_biscuit','바삭별 비스킷','작은 별 모양으로 구워 바삭한 소리가 기분 좋은 비스킷이에요. 봉투를 열면 버터 향이 솔솔 흘러나와, 멀찍이 숨어 있던 작은 친구도 코끝을 내밀고 주변을 살피게 돼요.',200,'/pets/items/biscuit_v1.webp',318,8500,1200,280,20,0,'fish','작은 별 모양으로 구워 바삭한 소리가 기분 좋은 비스킷이에요. 봉투를 열면 버터 향이 솔솔 흘러나와, 멀찍이 숨어 있던 작은 친구도 코끝을 내밀고 주변을 살피게 돼요.',10000,false,false),
('bait_pet_macaron','포근꿈 마카롱','폭신한 크림을 사이에 넣고 분홍빛 리본으로 묶은 마카롱이에요. 반쪽을 조심히 건네고 기다리면, 수줍은 친구와 나란히 앉아 달콤한 오후를 나누는 상상을 하게 돼요.',300,'/pets/items/macaron_v1.webp',319,8500,1200,280,20,0,'fish','폭신한 크림을 사이에 넣고 분홍빛 리본으로 묶은 마카롱이에요. 반쪽을 조심히 건네고 기다리면, 수줍은 친구와 나란히 앉아 달콤한 오후를 나누는 상상을 하게 돼요.',10000,false,false),
('bait_pet_starter','포슬포슬 간식주머니','작은 과자들을 아낌없이 담아 포슬포슬한 끈으로 묶은 간식주머니예요. 어디로 산책을 나서든 주머니가 살짝 흔들리면, 함께 걸을 친구를 기다리는 마음까지 고소하게 퍼져요.',120,'/pets/items/starter_v1.webp',320,8000,1800,180,20,0,'fish','작은 과자들을 아낌없이 담아 포슬포슬한 끈으로 묶은 간식주머니예요. 어디로 산책을 나서든 주머니가 살짝 흔들리면, 함께 걸을 친구를 기다리는 마음까지 고소하게 퍼져요.',10000,false,false),
('bait_safe','이슬잎 경단','새벽의 맑은 이슬을 머금은 잎으로 감싼 촉촉한 경단이에요. 조용히 물에 띄우면 잎맥을 따라 은은한 향이 번져, 바다 한가운데에도 작은 풀숲이 생긴 듯해요.',57,'/items/baits/dewleaf-dumpling.png',102,8300,1500,180,20,0,'fish','새벽의 맑은 이슬을 머금은 잎으로 감싼 촉촉한 경단이에요. 조용히 물에 띄우면 잎맥을 따라 은은한 향이 번져, 바다 한가운데에도 작은 풀숲이 생긴 듯해요.',10000,true,false),
('bait_sea_memory','바다기억 조개알','여러 해 동안 파도에 다듬어진 조개 안에 바다의 향을 담았어요. 어느 해안에서 열어 보아도 그곳의 바람을 닮은 냄새가 나, 고향을 기억하는 작은 상자라고 불려요.',84,'/items/baits/sea-memory-clam-pearl.png',104,8650,1200,130,20,0,'fish','여러 해 동안 파도에 다듬어진 조개 안에 바다의 향을 담았어요. 어느 해안에서 열어 보아도 그곳의 바람을 닮은 냄새가 나, 고향을 기억하는 작은 상자라고 불려요.',10000,false,false),
('bait_shell_crumbs','조개 부스러기','해변에서 모은 조개를 곱게 부수고 고소한 향을 더했어요. 햇빛 아래 펼쳐 놓으면 자잘한 무늬들이 반짝여, 누군가 모래 위에 써 둔 짧은 편지처럼 보여요.',46,'/items/baits/shell-crumbs.png',111,8600,1400,0,0,0,'fish','해변에서 모은 조개를 곱게 부수고 고소한 향을 더했어요. 햇빛 아래 펼쳐 놓으면 자잘한 무늬들이 반짝여, 누군가 모래 위에 써 둔 짧은 편지처럼 보여요.',10000,true,false),
('bait_shooting_star_tail','별똥별 꼬리젤리','하늘을 가로지른 별똥별의 꼬리를 닮은 길쭉한 젤리예요. 엉뚱한 물건을 유난히 좋아하지만, 가끔은 주머니 깊이 숨겨 둔 소중한 이야기를 슬쩍 보여 줄지도 몰라요.',46,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/shooting-star-tail-jelly-teal.png',122,9920,0,0,80,0,'fish','하늘을 가로지른 별똥별의 꼬리를 닮은 길쭉한 젤리예요. 엉뚱한 물건을 유난히 좋아하지만, 가끔은 주머니 깊이 숨겨 둔 소중한 이야기를 슬쩍 보여 줄지도 몰라요.',10000,false,false),
('bait_snowflake_salt','눈꽃 소금사탕','첫눈처럼 가벼운 소금 알갱이를 모아 투명한 사탕으로 굳혔어요. 물에 닿으면 가장자리부터 작은 눈꽃이 피었다가 사라져, 따뜻한 바다에도 잠깐의 겨울을 선물해요.',52,'https://ewafafphiovbpjwogwzn.supabase.co/storage/v1/object/public/collectibles/items/baits/snowflake-salt-candy.png',121,6800,3000,200,0,0,'fish','첫눈처럼 가벼운 소금 알갱이를 모아 투명한 사탕으로 굳혔어요. 물에 닿으면 가장자리부터 작은 눈꽃이 피었다가 사라져, 따뜻한 바다에도 잠깐의 겨울을 선물해요.',10000,false,false),
('bait_special','달빛 진주새우','달빛이 고인 웅덩이에서 헤엄치던 진주빛 새우예요. 작은 몸을 움직일 때마다 은은한 빛이 따라 흘러, 낚싯줄 끝에 달을 한 조각 걸어 둔 것 같아요.',null,'/items/baits/special.png',107,0,9870,100,30,0,'fish','달빛이 고인 웅덩이에서 헤엄치던 진주빛 새우예요. 작은 몸을 움직일 때마다 은은한 빛이 따라 흘러, 낚싯줄 끝에 달을 한 조각 걸어 둔 것 같아요.',10000,false,false),
('bait_starlight_wax','별빛 밀랍','별이 유난히 낮게 뜬 밤에 밀랍을 얇게 펴서 굳혔어요. 손바닥의 온기만으로도 희미한 빛이 살아나, 아직 끝나지 않은 밤하늘의 이야기를 들려줘요.',41,'/items/baits/starlight-wax.png',119,9950,0,0,50,0,'fish','별이 유난히 낮게 뜬 밤에 밀랍을 얇게 펴서 굳혔어요. 손바닥의 온기만으로도 희미한 빛이 살아나, 아직 끝나지 않은 밤하늘의 이야기를 들려줘요.',10000,true,false),
('bait_zigzag_jelly','지그재그 젤리','서로 다른 맛의 젤리를 번갈아 꼬아 만든 알록달록한 간식이에요. 한 입마다 다른 풍경이 떠오른다는 말에, 섬의 아이들은 여행을 떠나는 날이면 꼭 하나씩 챙겨요.',126,'/items/baits/zigzag-jelly.png',113,10000,0,0,0,0,'fish','서로 다른 맛의 젤리를 번갈아 꼬아 만든 알록달록한 간식이에요. 한 입마다 다른 풍경이 떠오른다는 말에, 섬의 아이들은 여행을 떠나는 날이면 꼭 하나씩 챙겨요.',10000,true,true)
